    protected override void WndProc(ref Message m){if(m.Msg==0x84&&WindowState==FormWindowState.Normal){long p=m.LParam.ToInt64();var at=PointToClient(new Point((short)p,(short)(p>>16)));bool left=at.X<7,right=at.X>=ClientSize.Width-7,top=at.Y<7,bottom=at.Y>=ClientSize.Height-7;int hit=top?(left?13:right?14:12):bottom?(left?16:right?17:15):left?10:right?11:0;if(hit!=0){m.Result=(IntPtr)hit;return;}}base.WndProc(ref m);}
