    async Task Guard(Func<Task> action){if(selected==null){status.Text="Выберите телефон.";return;}busy=true;foreach(var b in actions)b.Enabled=false;try{await action();}catch(Exception error){status.Text="Операция не выполнена: "+error.Message;}finally{busy=false;foreach(var b in actions)b.Enabled=true;}}
    async Task<Dictionary<string,object>> Request(string method,string url,object body=null){using(HttpResponseMessage response=method=="GET"?await http.GetAsync(url):await http.PostAsync(url,new StringContent(json.Serialize(body),System.Text.Encoding.UTF8,"application/json"))){string raw=await response.Content.ReadAsStringAsync();var value=json.Deserialize<Dictionary<string,object>>(raw);if(!response.IsSuccessStatusCode)throw new Exception(value.ContainsKey("error")?value["error"].ToString():"HTTP error");return value;}}
    static Dictionary<string,object> Obj(object v){return v as Dictionary<string,object>??new Dictionary<string,object>();}static string Str(Dictionary<string,object> v,string k){return v.ContainsKey(k)&&v[k]!=null?v[k].ToString():"—";}static bool Bool(Dictionary<string,object> v,string k){return v.ContainsKey(k)&&v[k] is bool&&(bool)v[k];}static object[] Arr(object v){var array=v as object[];if(array!=null)return array;var list=v as System.Collections.IList;if(list==null)return new object[0];var result=new object[list.Count];list.CopyTo(result,0);return result;}
    static string Translate(string state){var labels=new Dictionary<string,string>{{"running","Работает"},{"paused","Пауза"},{"stopped","Остановлен"},{"assigned","Назначен"},{"installed","Установлен"},{"starting","Запускается"},{"waiting","Ожидает"},{"error","Ошибка"},{"downloading","Загружается"},{"pending","Ожидает отправки"},{"received","Получено"},{"applied","Применено"},{"receiving","Принимает настройки"}};return labels.ContainsKey(state)?labels[state]:state;}
    static string Step(string value){var labels=new Dictionary<string,string>{{"farming","Фарм"},{"monitoring","Наблюдение"},{"revive","Возрождение"},{"waiting_after_revive","Ожидание после возрождения"},{"restore_stats","Восстановление характеристик"},{"buy_supplies","Закупка расходников"},{"auto_purchase","Автоматическая закупка"},{"red_weight_dismantle","Разбор при перегрузе"},{"open_farm_map","Открытие карты"},{"verify_arrival","Проверка прибытия"},{"verify_map_marker","Проверка точки на карте"},{"enable_autobattle","Включение автобоя"},{"recognizing_screen","Распознавание экрана"},{"screen_locked","Экран заблокирован"},{"manual_control","Ручное управление"},{"accessibility_permission_required","Нужна служба специальных возможностей"},{"game_not_foreground","Игра не на экране"},{"unrecognized_game_screen","Неизвестный экран игры"},{"farm_point_required","Нужна точка фарма"},{"launch_game","Запуск игры"},{"waiting_game_launch","Ожидание запуска игры"},{"wake_power_saving","Выход из игрового энергосбережения"}};return labels.ContainsKey(value)?labels[value]:value;}
    static string StatusLine(Dictionary<string,object> bot,Dictionary<string,object> saved){string when="—";if(bot.ContainsKey("updatedAt"))try{when=new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc).AddMilliseconds(Convert.ToDouble(bot["updatedAt"])).ToLocalTime().ToString("HH:mm:ss");}catch{}return "Шаг: "+Step(Str(bot,"step"))+" · точка: "+Str(bot,"activePoint")+" · отчёт: "+when+"\nНастройки: "+(Bool(saved,"pending")?"ожидают отправки":Translate(Str(bot,"settingsStatus")))+" · получено / применено: "+Str(bot,"receivedRevision")+" / "+Str(bot,"appliedRevision")+" · причина: "+Step(Str(bot,"reason"))+" · ошибка: "+Step(Str(bot,"error"));}
    async Task RefreshPhones(){if(loading)return;loading=true;try{var result=await Request("GET","/bot/v1/phones");phones.Rows.Clear();int select=-1;foreach(var raw in Arr(result["phones"])){var p=Obj(raw);var bot=Obj(p.ContainsKey("bot")?p["bot"]:null);var saved=Obj(p.ContainsKey("profile")?p["profile"]:null);var row=phones.Rows[phones.Rows.Add(PhoneTitle(p,saved),Bool(p,"online")?"Доступен":"Не в сети",Str(bot,"botId")+" / "+Str(bot,"version"),(Bool(p,"online")?"":"Последнее: ")+Translate(Str(bot,"status")))];string botState=Str(bot,"status");row.Cells[3].Style.ForeColor=botState=="error"?Color.FromArgb(255,137,137):botState=="running"?Mint:Color.Silver;row.Tag=Str(p,"id");if((string)row.Tag==selected){select=row.Index;if(!dirty)status.Text=StatusLine(bot,saved);}}if(select>=0)phones.Rows[select].Selected=true;else if(phones.Rows.Count>0){phones.Rows[0].Selected=true;selected=phones.Rows[0].Tag as string;profile=null;}}catch{status.Text="HTTP API недоступен. Откройте панель повторно после восстановления сервиса.";}finally{loading=false;}if(profile==null&&selected!=null)await LoadProfile();}
    static string PhoneTitle(Dictionary<string,object> phone,Dictionary<string,object> saved){var identity=Obj(saved.ContainsKey("identity")?saved["identity"]:null);string name=Str(identity,"characterName"),provider=Str(identity,"provider");return (name!="—"&&name!=""?name+" · ":"")+Str(phone,"name")+" · "+Str(phone,"country")+(provider!="—"&&provider!=""?" · "+provider:"");}
    void EditIdentity(){var identity=Obj(profile.ContainsKey("identity")?profile["identity"]:null);using(var dialog=new BotWindow{Text="Персонаж и поставщик телефона",Size=new Size(560,340),StartPosition=FormStartPosition.CenterParent}){var fields=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(20)};var name=new TextBox{Width=480,MaxLength=80,BackColor=Surface,ForeColor=Color.White,Text=Str(identity,"characterName")=="—"?"":Str(identity,"characterName")};var provider=new ComboBox{Width=480,DropDownStyle=ComboBoxStyle.DropDownList,BackColor=Surface,ForeColor=Color.White};provider.Items.AddRange(new object[]{"Не указан","VMOS","UgPhone","Другое"});provider.SelectedItem=Str(identity,"provider");if(provider.SelectedIndex<0)provider.SelectedIndex=0;fields.Controls.Add(new Label{Text="Имя персонажа",AutoSize=true});fields.Controls.Add(name);fields.Controls.Add(new Label{Text="Поставщик телефона",AutoSize=true,Margin=new Padding(3,16,3,3)});fields.Controls.Add(provider);var save=new BotButton{Text="Сохранить",Width=480,Height=44,BackColor=Mint,ForeColor=Background,Margin=new Padding(3,20,3,3)};fields.Controls.Add(save);save.Click+=async(s,e)=>{save.Enabled=false;try{var result=await Request("POST","/bot/v1/devices/"+selected+"/identity",new{characterName=name.Text,provider=provider.SelectedIndex==0?"":Convert.ToString(provider.SelectedItem)});profile["identity"]=result["identity"];await RefreshPhones();dialog.Close();}catch(Exception error){MessageBox.Show(dialog,error.Message,"Не удалось сохранить");save.Enabled=true;}};dialog.Controls.Add(fields);fields.BringToFront();dialog.ShowDialog(this);}}
    async Task LoadProfile(){loading=true;try{profile=await Request("GET","/bot/v1/devices/"+selected+"/profile");settings=Obj(profile["settings"]);farm.Checked=Bool(settings,"farm_enabled");recovery.Checked=Bool(settings,"recovery_enabled");dismantle.Checked=Bool(settings,"auto_dismantle_enabled");autostart.Checked=Bool(settings,"autostart_enabled");points.Clear();foreach(var p in Arr(settings["farm_map_spots"]))points.Add(Obj(p));RefreshSpots(0);dirty=false;status.Text=Bool(profile,"pending")?"Настройки сохранены на ПК, ожидают передачи телефону.":"Профиль загружен. Точки и маршрут — в F · Настройка фарма.";}catch{status.Text="Не удалось прочитать настройки телефона.";}finally{loading=false;}}
    async Task LoadMaps(){try{var bytes=await http.GetByteArrayAsync("/bot/v1/assets/lordnine/index.json");var index=json.Deserialize<Dictionary<string,object>>(System.Text.Encoding.UTF8.GetString(bytes));foreach(var item in Arr(index["maps"])){var m=Obj(item);mapItems.Add(m);maps.Items.Add(Str(m,"label"));if(!regions.Items.Contains(Str(m,"tab_label")))regions.Items.Add(Str(m,"tab_label"));}if(maps.Items.Count>0)maps.SelectedIndex=0;}catch{status.Text="Карты Lord Nine недоступны.";}}
    void LoadMap(){if(maps.SelectedIndex<0)return;syncRegion=true;try{regions.SelectedItem=Str(mapItems[maps.SelectedIndex],"tab_label");}finally{syncRegion=false;}string name=Str(mapItems[maps.SelectedIndex],"image");string file=Path.Combine(root,"lordnine","maps",name);if(!File.Exists(file))return;Image old=picture.Image;using(var stream=File.OpenRead(file))using(var bitmap=new Bitmap(stream)){mapCrop=wholeMap?new RectangleF(0,0,1,1):new RectangleF(.265f,.095f,.470f,.850f);var crop=Rectangle.FromLTRB((int)Math.Round(bitmap.Width*mapCrop.Left),(int)Math.Round(bitmap.Height*mapCrop.Top),(int)Math.Round(bitmap.Width*mapCrop.Right),(int)Math.Round(bitmap.Height*mapCrop.Bottom));picture.Image=bitmap.Clone(crop,bitmap.PixelFormat);}if(old!=null)old.Dispose();SetZoom(1);RefreshPointList();picture.Invalidate();}
    Rectangle ImageRect(){if(picture.Image==null)return Rectangle.Empty;double scale=Math.Min(picture.Width/(double)picture.Image.Width,picture.Height/(double)picture.Image.Height);int w=(int)(picture.Image.Width*scale),h=(int)(picture.Image.Height*scale);return new Rectangle((picture.Width-w)/2,(picture.Height-h)/2,w,h);}
    void PlacePoint(MouseEventArgs e){if(busy||settings==null||spots.SelectedIndex<0||maps.SelectedIndex<0)return;var spot=points[spots.SelectedIndex];if(Str(spot,"map_id")!=Str(mapItems[maps.SelectedIndex],"id")){status.Text="Выберите карту выбранной локации.";return;}Rectangle r=ImageRect();if(!r.Contains(e.Location))return;var point=new object[]{mapCrop.X+mapCrop.Width*(e.X-r.X)/(double)r.Width,mapCrop.Y+mapCrop.Height*(e.Y-r.Y)/(double)r.Height};if(e.Button==MouseButtons.Right)spot["teleport_point"]=point;else{var list=new List<object>(Arr(spot["map_points"]));int near=list.FindIndex(item=>NearPoint(Arr(item),point));if(near>=0)list.RemoveAt(near);else{if(list.Count>=256)return;list.Add(point);}spot["map_points"]=list.ToArray();}dirty=true;RefreshPointList();picture.Invalidate();}
    void PaintPoints(Graphics g){if(spots.SelectedIndex<0||maps.SelectedIndex<0)return;var spot=points[spots.SelectedIndex];if(Str(spot,"map_id")!=Str(mapItems[maps.SelectedIndex],"id"))return;Rectangle r=ImageRect();int number=0;foreach(var p in Arr(spot["map_points"])){DrawPoint(g,r,Arr(p),Mint);var xy=Arr(p);if(xy.Length==2)g.DrawString((++number).ToString(),Font,Brushes.White,r.X+((float)Convert.ToDouble(xy[0])-mapCrop.X)/mapCrop.Width*r.Width+6,r.Y+((float)Convert.ToDouble(xy[1])-mapCrop.Y)/mapCrop.Height*r.Height); }if(spot.ContainsKey("teleport_point"))DrawPoint(g,r,Arr(spot["teleport_point"]),Color.Orange);}
    void DrawPoint(Graphics g,Rectangle r,object[] p,Color color){if(p.Length!=2)return;float x=r.X+((float)Convert.ToDouble(p[0])-mapCrop.X)/mapCrop.Width*r.Width,y=r.Y+((float)Convert.ToDouble(p[1])-mapCrop.Y)/mapCrop.Height*r.Height;using(var pen=new Pen(color,3)){g.DrawEllipse(pen,x-5,y-5,10,10);}}
    void RefreshSpots(int index){spots.Items.Clear();foreach(var p in points)spots.Items.Add((Str(settings,"active_farm_map_spot_id")==Str(p,"id")?"● ":"○ ")+Str(p,"label"));if(spots.Items.Count>0)spots.SelectedIndex=Math.Min(Math.Max(index,0),spots.Items.Count-1);picture.Invalidate();}
    void OpenFarmEditor(){using(var dialog=new BotWindow{Text="Фарм: "+(phones.SelectedRows.Count>0?Convert.ToString(phones.SelectedRows[0].Cells[0].Value):"телефон"),Size=new Size(1500,950),MinimumSize=new Size(1150,740),StartPosition=FormStartPosition.CenterParent,BackColor=Background,ForeColor=Color.White,Font=Font}){var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=100,AutoScroll=true};var editorStatus=new Label{Dock=DockStyle.Bottom,Height=86,ForeColor=Mint,Padding=new Padding(12)};var editorPoll=new Timer{Interval=500};editorPoll.Tick+=(s,e)=>editorStatus.Text=status.Text;editorStatus.Text=status.Text;editorPoll.Start();var save=new BotButton{Text="Сохранить и отправить",Width=240,Height=40,BackColor=Mint,ForeColor=Background};save.Click+=async(s,e)=>await Save();var copy=new BotButton{Text="Копировать профиль…",Width=220,Height=40};copy.Click+=async(s,e)=>await Copy();var close=new BotButton{Text="Закрыть",Width=120,Height=40};close.Click+=(s,e)=>dialog.Close();footer.Controls.Add(save);footer.Controls.Add(copy);var from=new BotButton{Text="Копировать с телефона…",Width=240,Height=40};from.Click+=async(s,e)=>await CopyFrom();footer.Controls.Add(from);footer.Controls.Add(close);dialog.Controls.Add(mapEditor);dialog.Controls.Add(editorStatus);dialog.Controls.Add(footer);mapEditor.BringToFront();dialog.Shown+=(s,e)=>ResizeMap();try{dialog.ShowDialog(this);}finally{editorPoll.Stop();editorPoll.Dispose();dialog.Controls.Remove(mapEditor);ResizeMap();}}}
    static bool NearPoint(object[] a,object[] b){if(a.Length!=2||b.Length!=2)return false;return Math.Pow(Convert.ToDouble(a[0])-Convert.ToDouble(b[0]),2)+Math.Pow(Convert.ToDouble(a[1])-Convert.ToDouble(b[1]),2)<=.025*.025;}
    void SetZoom(double value){zoom=Math.Max(.5,Math.Min(4,value));zoomLabel.Text=Math.Round(zoom*100)+"%";ResizeMap();}
    void ResizeMap(){if(picture.Image==null)return;double fit=Math.Min(Math.Max(1,mapViewport.ClientSize.Width-20)/(double)picture.Image.Width,Math.Max(1,mapViewport.ClientSize.Height-20)/(double)picture.Image.Height);picture.Size=new Size(Math.Max(1,(int)(picture.Image.Width*fit*zoom)),Math.Max(1,(int)(picture.Image.Height*fit*zoom)));picture.Location=new Point(Math.Max(0,(mapViewport.ClientSize.Width-picture.Width)/2),Math.Max(0,(mapViewport.ClientSize.Height-picture.Height)/2));picture.Invalidate();}
    void RefreshPointList(){pointList.Controls.Clear();if(spots.SelectedIndex<0)return;var spot=points[spots.SelectedIndex];string map=Str(spot,"map_id");var plan=Obj(spot.ContainsKey("travel_plan")?spot["travel_plan"]:null);bool chain=(!plan.ContainsKey("enabled")||Bool(plan,"enabled"))&&(map.Contains("tyriosa")||Str(plan,"type")=="tyriosa_floor_chain");routeLabel.Text=chain?"Маршрут: Desert → Entrance → 1F"+(map.Contains("3f")||Str(plan,"target_floor")=="3F"?" → 3F · Move #2 → Walk":map.Contains("2f")||Str(plan,"target_floor")=="2F"?" → 2F":"")+" → точка фарма. Старт — Entrance.":"Телепорт → "+(!spot.ContainsKey("run_after_teleport")||Bool(spot,"run_after_teleport")?"точка фарма":"автобой")+". План: "+Str(plan,"type");routeLabel.MaximumSize=new Size(290,0);pointList.Controls.Add(routeLabel);int number=0;foreach(var value in Arr(spot["map_points"])){var xy=Arr(value);if(xy.Length!=2)continue;int index=number++;var button=new BotButton{Text="#"+(index+1)+" "+Convert.ToDouble(xy[0]).ToString("0.000")+", "+Convert.ToDouble(xy[1]).ToString("0.000")+" ×",AutoSize=true,BackColor=Surface,ForeColor=Mint,FlatStyle=FlatStyle.Flat};button.Click+=(s,e)=>{if(busy)return;var list=new List<object>(Arr(spot["map_points"]));if(index<list.Count)list.RemoveAt(index);spot["map_points"]=list.ToArray();dirty=true;RefreshPointList();picture.Invalidate();};pointList.Controls.Add(button);}if(Arr(spot.ContainsKey("teleport_point")?spot["teleport_point"]:null).Length==2){var clear=new BotButton{Text="Убрать Fast Travel ×",AutoSize=true};clear.Click+=(s,e)=>{if(busy)return;spot["teleport_point"]=null;dirty=true;RefreshPointList();picture.Invalidate();};pointList.Controls.Add(clear);}}
    async Task<Dictionary<string,object>> WaitJob(Dictionary<string,object> job){for(int i=0;i<180;i++){await Task.Delay(1000);var result=await Request("GET","/bot/v1/jobs/"+Str(job,"id"));if(Str(result,"status")=="failed")throw new Exception(Str(result,"error"));if(Str(result,"status")=="done")return Obj(result["result"]);}throw new Exception("Результат неизвестен; повторно не отправляется.");}
    async Task InspectMap(bool capture){if(dirty){status.Text="Сначала сохраните настройки.";return;}if(spots.SelectedIndex<0)return;var spot=points[spots.SelectedIndex];await Guard(async()=>{status.Text="Фарм приостановлен. Проверяется Current Location и стрелка на телефоне…";var job=await Request("POST","/bot/v1/devices/"+selected+"/action",new{op="editor",kind=capture?"capture":"point",mapId=Str(spot,"map_id")});var result=await WaitJob(job);if(!capture){var xy=Arr(result["point"]);var list=new List<object>(Arr(spot["map_points"]));int near=list.FindIndex(item=>NearPoint(Arr(item),xy));if(near>=0)list[near]=xy;else{if(list.Count>=256)throw new Exception("Не более 256 точек.");list.Add(xy);}spot["map_points"]=list.ToArray();dirty=true;RefreshPointList();picture.Invalidate();status.Text="Положение добавлено в редактор. Сохраните настройки. Бот оставлен на паузе.";return;}var shotJob=await Request("POST","/v1/devices/"+selected+"/commands",new{command="screenshot",args=new{format="png"}});Dictionary<string,object> shot=null;for(int i=0;i<90;i++){await Task.Delay(1000);var response=await Request("GET","/v1/devices/"+selected+"/commands/"+Str(shotJob,"id"));if(Str(response,"status")=="done"){var envelope=Obj(response["result"]);if(!Bool(envelope,"ok"))throw new Exception("Не получен кадр.");shot=Obj(envelope["result"]);break;}}if(shot==null)throw new Exception("Не получен кадр.");using(var stream=new MemoryStream(Convert.FromBase64String(Str(shot,"image"))))using(var bitmap=new Bitmap(stream)){var rect=Rectangle.FromLTRB((int)Math.Round(bitmap.Width*.015),(int)Math.Round(bitmap.Height*.065),(int)Math.Round(bitmap.Width*.385),(int)Math.Round(bitmap.Height*.17));using(var crop=bitmap.Clone(rect,bitmap.PixelFormat)){using(var png=new MemoryStream()){crop.Save(png,System.Drawing.Imaging.ImageFormat.Png);var templates=Obj(settings.ContainsKey("current_location_templates")?settings["current_location_templates"]:null);templates[Str(spot,"map_id")]=Convert.ToBase64String(png.ToArray());settings["current_location_templates"]=templates;dirty=true;}using(var file=new SaveFileDialog{Title="Экспортировать образец Current Location",Filter="PNG (*.png)|*.png",FileName=Str(spot,"map_id")+"-current-location.png"})if(file.ShowDialog(this)==DialogResult.OK)crop.Save(file.FileName,System.Drawing.Imaging.ImageFormat.Png);}}status.Text="Образец Current Location добавлен в настройки этой карты. Сохраните и отправьте; бот оставлен на паузе.";});}
    async Task CopyFrom(){if(busy)return;using(var dialog=new BotWindow{Text="Копировать настройки фарма с телефона",Size=new Size(520,420),StartPosition=FormStartPosition.CenterParent,BackColor=Background,ForeColor=Color.White}){var list=new ListBox{Dock=DockStyle.Fill,BackColor=Surface,ForeColor=Color.White};var ids=new List<string>();foreach(DataGridViewRow row in phones.Rows)if((string)row.Tag!=selected){ids.Add((string)row.Tag);list.Items.Add(row.Cells[0].Value);}var ok=new BotButton{Text="Копировать в редактор",Dock=DockStyle.Bottom,Height=42,DialogResult=DialogResult.OK};dialog.Controls.Add(list);dialog.Controls.Add(ok);if(dialog.ShowDialog(this)!=DialogResult.OK||list.SelectedIndex<0)return;await Guard(async()=>{var source=await Request("GET","/bot/v1/devices/"+ids[list.SelectedIndex]+"/profile");var imported=Obj(source["settings"]);if(Arr(imported["farm_map_spots"]).Length==0)throw new Exception("У телефона нет настроенных локаций.");loading=true;try{settings=imported;points.Clear();foreach(var raw in Arr(settings["farm_map_spots"]))points.Add(Obj(raw));farm.Checked=Bool(settings,"farm_enabled");recovery.Checked=Bool(settings,"recovery_enabled");dismantle.Checked=Bool(settings,"auto_dismantle_enabled");autostart.Checked=Bool(settings,"autostart_enabled");RefreshSpots(0);dirty=true;status.Text="Профиль скопирован в редактор. Проверьте точки, затем сохраните настройки.";}finally{loading=false;}});}}
    async Task SendFarm(){if(spots.SelectedIndex<0)return;settings["active_farm_map_spot_id"]=points[spots.SelectedIndex]["id"];farm.Checked=true;dirty=true;await Save();if(dirty)return;await Guard(async()=>{await Action("stop",null);await Action("start",null);});}
    void EditTravelPlan(){
        if(spots.SelectedIndex<0)return;
        var spot=points[spots.SelectedIndex];var plan=Obj(spot.ContainsKey("travel_plan")?spot["travel_plan"]:null);
        using(var dialog=new BotWindow{Text="Локация и переход",Size=new Size(510,370),StartPosition=FormStartPosition.CenterParent,BackColor=Background,ForeColor=Color.White,Font=Font}){
            var fields=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(16)};
            var enabled=new CheckBox{Text="Локация включена",Checked=!spot.ContainsKey("enabled")||Bool(spot,"enabled"),AutoSize=true};
            var run=new CheckBox{Text="Идти к точке фарма после телепорта",Checked=!spot.ContainsKey("run_after_teleport")||Bool(spot,"run_after_teleport"),AutoSize=true};
            var kind=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=450,BackColor=Surface,ForeColor=Color.White};
            kind.Items.AddRange(new object[]{"Автоматически по карте","Без плана перехода","Гробница Тириосы — этажи","Земли мертвеца — районы"});
            kind.SelectedIndex=!spot.ContainsKey("travel_plan")?0:!Bool(plan,"enabled")&&plan.ContainsKey("enabled")?1:Str(plan,"type")=="tyriosa_floor_chain"?2:Str(plan,"type")=="deadmans_district_chain"?3:0;
            var target=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=450,BackColor=Surface,ForeColor=Color.White};
            Action refresh=()=>{target.Items.Clear();target.Enabled=kind.SelectedIndex>=2;if(kind.SelectedIndex==2)target.Items.AddRange(new object[]{"1F","2F","3F"});else if(kind.SelectedIndex==3)target.Items.AddRange(new object[]{"1","2","3"});if(target.Items.Count>0){string old=Str(plan,kind.SelectedIndex==2?"target_floor":"target_district");int index=target.Items.IndexOf(old);target.SelectedIndex=index>=0?index:0;}};
            kind.SelectedIndexChanged+=(s,e)=>refresh();refresh();
            fields.Controls.Add(enabled);fields.Controls.Add(run);fields.Controls.Add(new Label{Text="План перехода",AutoSize=true,Margin=new Padding(0,15,0,6)});fields.Controls.Add(kind);fields.Controls.Add(new Label{Text="Целевой этаж / район",AutoSize=true});fields.Controls.Add(target);
            fields.Controls.Add(new Label{Text="Изменения сохранятся только после отправки настроек телефона.",Width=450,Height=42,ForeColor=Color.Silver});
            var ok=new BotButton{Text="Применить в редакторе",Dock=DockStyle.Bottom,Height=42,DialogResult=DialogResult.OK,BackColor=Mint,ForeColor=Background,FlatStyle=FlatStyle.Flat};dialog.Controls.Add(fields);dialog.Controls.Add(ok);
            if(dialog.ShowDialog(this)!=DialogResult.OK)return;
            spot["enabled"]=enabled.Checked;spot["run_after_teleport"]=run.Checked;
            if(kind.SelectedIndex==0)spot.Remove("travel_plan");
            else if(kind.SelectedIndex==1)spot["travel_plan"]=new Dictionary<string,object>{{"enabled",false}};
            else {var next=new Dictionary<string,object>(plan);next["enabled"]=true;next["type"]=kind.SelectedIndex==2?"tyriosa_floor_chain":"deadmans_district_chain";next.Remove(kind.SelectedIndex==2?"target_district":"target_floor");next[kind.SelectedIndex==2?"target_floor":"target_district"]=target.SelectedItem.ToString();spot["travel_plan"]=next;}
            dirty=true;RefreshSpots(spots.SelectedIndex);
        }
    }
    async Task Save(){await Guard(async()=>{settings["farm_enabled"]=farm.Checked;settings["recovery_enabled"]=recovery.Checked;settings["auto_dismantle_enabled"]=dismantle.Checked;settings["autostart_enabled"]=autostart.Checked;settings["farm_map_spots"]=points.ToArray();if(points.Count==0)settings["active_farm_map_spot_id"]=null;var result=await Request("POST","/bot/v1/devices/"+selected+"/settings",new{settings=settings});dirty=false;status.Text="Редакция "+Str(result,"revision")+": сохранено на ПК, ожидает подтверждения телефона.";});}
    async Task Action(string op,string value){if((op=="start"||op=="resume")&&dirty){status.Text="Сначала сохраните настройки.";return;}var body=new Dictionary<string,object>{{"op",op}};if(op=="assign")body["botId"]=value;if(op=="install")body["version"]=value;var job=await Request("POST","/bot/v1/devices/"+selected+"/action",body);string id=Str(job,"id");status.Text="Выполняется: "+op;for(int i=0;i<180;i++){await Task.Delay(1000);var result=await Request("GET","/bot/v1/jobs/"+id);if(Str(result,"status")=="failed"){status.Text="Ошибка: "+Str(result,"error");return;}if(Str(result,"status")=="done"){var state=Obj(result.ContainsKey("result")?result["result"]:null);status.Text=Translate(Str(state,"status"))+" · шаг: "+Str(state,"step")+" · настройки: "+Translate(Str(state,"settingsStatus"))+" / "+Str(state,"appliedRevision")+" · ошибка: "+Str(state,"error");return;}}status.Text="Результат пока неизвестен. Запросите статус; действие автоматически не повторяется.";}
    async Task Copy(){if(selected==null)return;using(var dialog=new BotWindow{Text="Копирование настроек",Size=new Size(620,520),StartPosition=FormStartPosition.CenterParent,BackColor=Background,ForeColor=Color.White}){var list=new CheckedListBox{Dock=DockStyle.Fill,BackColor=Surface,ForeColor=Color.White,BorderStyle=BorderStyle.None,CheckOnClick=true};var ids=new List<string>();foreach(DataGridViewRow row in phones.Rows)if((string)row.Tag!=selected){string id=(string)row.Tag;ids.Add(id);list.Items.Add(row.Cells[0].Value,Array.IndexOf(InitialCopyTargets??new string[0],id)>=0);}var ok=new BotButton{Text="Скопировать сохранённые настройки",Dock=DockStyle.Bottom,Height=44,DialogResult=DialogResult.OK,BackColor=Mint,ForeColor=Background};dialog.Controls.Add(list);dialog.Controls.Add(ok);list.BringToFront();if(dialog.ShowDialog(this)==DialogResult.OK){var targets=new List<string>();foreach(int index in list.CheckedIndices)targets.Add(ids[index]);if(targets.Count==0){status.Text="Не выбраны телефоны для копирования.";return;}await Guard(async()=>{await Request("POST","/bot/v1/devices/"+selected+"/copy",new{targets=targets});status.Text="Копии сохранены; передача выполняется назначенным телефонам.";});}}}
    void ImportProfile(){if(settings==null||busy)return;try{using(var file=new OpenFileDialog{Title="Откройте runtime/windows.json из MultiBot",Filter="Профили MultiBot (*.json)|*.json"}){if(file.ShowDialog(this)!=DialogResult.OK)return;if(new FileInfo(file.FileName).Length>16000000)throw new Exception();var parser=new JavaScriptSerializer{MaxJsonLength=16000000};var data=parser.Deserialize<Dictionary<string,object>>(File.ReadAllText(file.FileName));var records=Obj(data.ContainsKey("windows")?data["windows"]:null);var eligible=new List<Dictionary<string,object>>();using(var dialog=new BotWindow{Text="Сопоставьте старое устройство с выбранным телефоном",Size=new Size(560,360),StartPosition=FormStartPosition.CenterParent,BackColor=Background,ForeColor=Color.White}){var list=new ListBox{Dock=DockStyle.Fill,BackColor=Surface,ForeColor=Color.White};foreach(var pair in records){var record=Obj(pair.Value);if(Str(record,"game_id")!="lordnine")continue;eligible.Add(record);list.Items.Add(Str(record,"alias")+" · "+Str(record,"name"));}var ok=new BotButton{Text="Импортировать в редактор выбранного телефона",Dock=DockStyle.Bottom,Height=44,DialogResult=DialogResult.OK};dialog.Controls.Add(list);dialog.Controls.Add(ok);if(dialog.ShowDialog(this)!=DialogResult.OK||list.SelectedIndex<0)return;var source=eligible[list.SelectedIndex];points.Clear();foreach(var raw in Arr(source["farm_map_spots"])){var original=Obj(raw);var point=new Dictionary<string,object>();foreach(var key in new[]{"id","map_id","label","enabled","teleport_point","run_after_teleport","map_points","travel_plan"})if(original.ContainsKey(key))point[key]=original[key];points.Add(point);}settings["active_farm_map_spot_id"]=source.ContainsKey("active_farm_map_spot_id")?source["active_farm_map_spot_id"]:null;farm.Checked=Bool(source,"farm_enabled");dirty=true;RefreshSpots(0);status.Text="Профиль импортирован в редактор. Проверьте телефон, локацию и точки, затем сохраните настройки.";}}}catch{status.Text="Не удалось импортировать профиль: выберите windows.json с записями Lord Nine.";}}
}}
